import os
import xlsxwriter  # type: ignore
from taf.ul.sc.perf.reports.benchmark.sheet import Sheet


class ExcelGenerator:
    def __init__(self, parsers, devices):
        self.parsers = parsers
        self.device = devices

        self.procdump_parser = self.parsers.pop(0)

    @staticmethod
    def _parse_data_from_path(parser, path):
        """
        Parse data from given path return as dictionary
        :param path: Path to directory with procdump files.
        :return: data: Directory with parsed data.
        """
        parser = parser(path)
        parser.parse()
        data = parser.get_data()
        if 'procinfo' in data.keys():
            del data['procinfo']
        return data

    def _save_data_from_all_devices(self):
        """
        Parse data for all processors and save in one dictionary.
        :return: data: Directory with data for all processors.
        """
        data = {self.device: self._parse_data_from_path(self.procdump_parser['parser'], self.procdump_parser['path'])}

        proc_directories = [file_name for file_name in os.listdir(self.procdump_parser['path'])
                            if 'procdump_' in file_name]
        for directory in proc_directories:
            path = os.path.join(self.procdump_parser['path'], directory, 'procdump')
            device_name = directory.replace('procdump_', '')
            data[device_name] = self._parse_data_from_path(self.procdump_parser['parser'], path)
        return data

    @staticmethod
    def _select_data_by_params(data, params):
        """
        Select data for all processors containing only params given in params list and timestamp.
        :param: data: Dictionary data for all parameters.
        :param: params: List with params names to select.
        :return: selected_data: Directory with selected data for all processors.
        """
        selected_data = {}
        if len(params):
            for device, value in data.items():
                device_data = {'systime': value['systime']}
                for param in params:
                    device_data[param] = value[param]
                selected_data[device] = device_data
        else:
            selected_data = data
        return selected_data

    def generate_excels(self, is_summary=False, params=[]):
        """
        Save data and generate summary excel or separate excels for all processors depending on is_summary value.
        :param is_summary: Default False, if True creates one excel with summary of all processors for given params.
        :param params: List of keys that are going to be added to summary excel.
        :return: self:
        """
        data = self._save_data_from_all_devices()
        if is_summary:
            selected_data = self._select_data_by_params(data, params)
            self._generate_summary_excel(selected_data)
        else:
            self._generate_separate_excels(data)
        return self

    def _generate_separate_excels(self, data):
        """
        Generate separate excels for all processors, create indexes and write data into workbooks.
        :param: data: Dictionary data for all parameters.
        """
        workbook = xlsxwriter.Workbook(os.path.join(self.procdump_parser['path'], self.device + '.xlsx'))

        sheet_index = Sheet(workbook, data[self.device]['systime'], data[self.device], 'index')
        self._write_data_to_workbook(data[self.device], workbook)

        if self.parsers:
            for parser in self.parsers:
                self._write_additional_data_to_workbook(parser['parser'], parser['path'], parser['title'], workbook)

        sheet_index.generate()
        workbook.worksheets_objs.sort(key=lambda x: x.name.split('_').pop() if x.name != 'index' else '1')
        workbook.close()
        self._generate_excels_for_all_devices(workbook, data)

    def _write_data(self, workbook, timestamp, data, device_name):
        """
        Writes data to given workbook.
        :param: workbook: Workbook to add worksheets.
        :param: timestamp: Array with time.
        :param: data: Dictionary with processor's benchmarking data.
        :param: device_name: Processed device name. If not summary excel, device name is empty.
        :return: workbook: Processed workbook.
        """
        sheets_chart = self._generate_chart_sheets(workbook, timestamp, data, device_name)
        sheets_table = self._generate_table_sheets(workbook, timestamp, data, device_name)
        for sheet in sheets_table:
            sheet.generate()
            chart_info = sheet.charts
            is_nested_table = sheet.is_nested
            sheets_chart[sheets_table.index(sheet)].set_charts(chart_info)
            sheets_chart[sheets_table.index(sheet)].generate(is_nested_table)

    def _generate_summary_excel(self, data):
        """
        Generate summary excel for all processors including params keys, create index and write data into workbooks.
        :param: params: List of keys that are going to be added to summary excel. If empty, all keys are added.
        """
        workbook = xlsxwriter.Workbook(os.path.join(self.procdump_parser['path'], 'Devices_Summary.xlsx'))
        sheet_index = Sheet(workbook, data[self.device]['systime'], data[self.device], 'index')
        self._write_data_to_workbook(data[self.device], workbook, self.device + '_')

        if self.parsers:
            for parser in self.parsers:
                self._write_additional_data_to_workbook(parser['parser'], parser['path'], parser['title'], workbook,
                                                        self.device + '_')

        self._generate_excels_for_all_devices(workbook, data, True)
        sheet_index.generate()

        workbook.worksheets_objs.sort(
            key=lambda x: x.name.split('_').pop() if x.name != 'index' else '1')

        workbook.close()

    def _generate_excels_for_all_devices(self, workbook, data, is_summary=False):
        """
        Go through data for all processors without main and generate excels for them.
        :param: workbook: Workbook to add worksheets.
        :param: data: Dictionary with data for all processors.
        :param: is_summary: Default False, if True creates one excel with summary of all processors for given params.
        """
        for device, value in data.items():
            if device != self.device:
                if is_summary:
                    self._write_data_to_workbook(data[device], workbook, device + '_')
                else:
                    workbook = xlsxwriter.Workbook(
                        os.path.join(self.procdump_parser['path'], "procdump_" + device, "procdump", device + '.xlsx'))
                    sheet_index = Sheet(workbook, data[device]['systime'], data[device], 'index')
                    self._write_data_to_workbook(data[device], workbook)
                    sheet_index.generate()
                    workbook.close()

    def _write_data_to_workbook(self, data, workbook, device_name=""):
        """
        Prepare time list and writes data to given workbook.
        :param: data: Dictionary with processor's benchmarking data.
        :param: workbook: Workbook to add worksheets.
        :param: device_name: Processed device name. If not summary excel, device name is empty.
        :return: workbook: Processed workbook.
        """
        timestamp = data['systime']
        del data['systime']
        self._write_data(workbook, timestamp, data, device_name)

    def _write_additional_data_to_workbook(self, parser, path, title, workbook, device_name=''):
        """
        Parse DSP data, prepare time list and writes dsp data to given workbook.
        :param: workbook: Workbook to add worksheets.
        :param: device_name: Processed device name. If not summary excel, device name is empty.
        """
        data = self._parse_data_from_path(parser, path)
        timestamp = data['timestamp']
        del data['timestamp']
        self._write_data(workbook, timestamp, data, '{}{}{}'.format(device_name, title, '_'))

    @staticmethod
    def _generate_chart_sheets(workbook, timestamp, data, device_name=""):
        """
        Create Sheet with chart using given parameters.
        :param: workbook: Workbook to add worksheets.
        :param: timestamp: List with time column.
        :param: data: Dictionary with processor's benchmarking data.
        :param: device_name: Processed device name. If not summary excel, device name is empty.
        :return: sheet: Created sheet.
        """
        return [Sheet(workbook, timestamp, data[tasks], device_name + str(tasks) + "_chart") for tasks in data]

    @staticmethod
    def _generate_table_sheets(workbook, timestamp, data, device_name=""):
        """
        Create Sheet with table using given parameters.
        :param: workbook: Workbook to add worksheets.
        :param: timestamp: List with time column.
        :param: data: Dictionary with processor's benchmarking data.
        :param: device_name: Processed device name. If not summary excel, device name is empty.
        :return: sheet: Created sheet.
        """
        return [Sheet(workbook, timestamp, data[tasks], device_name + str(tasks) + "_table") for tasks in data]


